"""The cross-check comparators without Unity (unit P11): on the shipped Simulation Data, and with planted faults.

* X1 on the 109 shipped snapshots is G11 (981/981 columns compose from Value and K2/K3 under double_all);
* the DP8 RpmFirst anchor built from the shipped day snapshots alone reaches G20's 1380/1380;
* X3/X7/DP8/X6 report exactly the item a planted fault touches (the "C#" side is generated by the oracle);
* the check plumbing: statuses, vacuous parts, per-item CSVs.
"""

from __future__ import annotations

import copy
import csv
import math
from dataclasses import replace
from pathlib import Path

import pytest

from tufu_balance import crosscheck as X
from tufu_balance.crosscheck import composition, invariants, rpm
from tufu_balance.model import simcalc as sc
from tufu_balance.model import spawners as sp
from tufu_balance.model.data import load_simulation_data
from tufu_balance.model.snapshots import SimulationStat
from tufu_balance.unity import probes


@pytest.fixture(scope="module")
def env(db):
    return X.Env.load(db)


@pytest.fixture(scope="module")
def shipped(db):
    return load_simulation_data(db)


def _run(early, full, *, mode="free", override=False, records=(), job_dir=Path("."), daily=None):
    manifest = {"job_id": "synthetic", "mode": mode, "override": {"active": override}, "engine": {"counters": {}}}
    trace = None
    if daily is not None:
        from tufu_balance.unity.trace import Trace
        trace = Trace(manifest={}, daily=daily)
    return X.RunData(job_dir, manifest, early, full, [s.tc for s in full], trace, {}, list(records))


def _snaps(lst, snapshots):
    return [X.Snap(lst, i, s, None, []) for i, s in enumerate(snapshots)]


def _bump(x: float, n: int = 1) -> float:
    return float(probes.doubles(format(X.bits(x) + n & (2 ** 64 - 1), "016x"))[0])


def test_x1_on_the_shipped_snapshots_is_g11(env, shipped, tmp_path):
    run = _run(_snaps("Snapshots", shipped.snapshots), _snaps("TimeChunkSnapshots", shipped.time_chunk_snapshots))
    r = composition.check_x1(run, env, tmp_path)
    assert r.status == "pass" and r.items == 109 * 9 * 4 + 109 * 21 * 4  # 9 main + 21 other stats per snapshot
    rows = list(csv.DictReader((tmp_path / "X1.csv").open()))
    assert len(rows) == r.items and all(row["ok"] == "1" for row in rows)
    # one planted 1-ulp TotalValue
    bad = copy.deepcopy(shipped.time_chunk_snapshots)
    st = bad[7].stats[0]
    bad[7].stats[0] = replace(st, total_value=_bump(st.total_value))
    r = composition.check_x1(_run([], _snaps("TimeChunkSnapshots", bad)), env)
    assert r.status == "fail" and r.mismatches == 1
    assert r.examples[0]["field"] == "TotalValue" and r.examples[0]["index"] == 7 and r.examples[0]["ulps"] == 1


def _dp8_records(env, shipped, db):
    """Override records as the C# export writes them, from the oracle (the plumbing under test, not the numbers)."""
    defs = sp.load_spawners(db)
    chain = sc.initial_rpm()
    out = []
    for snap in shipped.time_chunk_snapshots:
        d = snap.time_chunk_index
        boss = sp.boss_for_location(snap.location, defs)
        kw = {"current_boss": boss.spawner_id if boss else None}
        enc = lambda data: [[env.runtime_id(sid), "".join(probes.dhex(v) for v in rpm._oracle_fields(x))]
                            for sid, x in data.items()]
        gpm = sc.calculate_spawner_data(env.ctx, rpm._shipped_state(env, snap, d, d), True, **kw)
        state = rpm._shipped_state(env, snap, d, d - 1)
        rf = sc.calculate_spawner_data(env.ctx, state, True, **kw)
        chain, _, _ = sc.calculate_rpm_value_time_chunk(env.ctx, state, rpm=chain)
        out.append({"day": d, "location": snap.location, "current_boss": env.runtime_id(boss.spawner_id) if boss else None,
                    "crosscheck_dp8": {"day": d, "gpm": enc(gpm), "rpm_first": {
                        "stats": [[k, probes.dhex(v)] for k, v in state.stats.items()], "spawners": enc(rf),
                        "rpm": [[k, probes.dhex(v)] for k, v in chain.items()]}}})
    return out


@pytest.mark.slow
def test_dp8_anchor_and_planted_faults(env, shipped, db, tmp_path):
    records = _dp8_records(env, shipped, db)
    run = _run([], [], mode="checkpoint", override=True, records=records)
    r = rpm.check_dp8(run, env, tmp_path)
    assert r.status == "pass", r.examples
    assert (r.counts["states"], r.counts["g20_cells"], r.counts["g20_matches"]) == (46, 1380, 1380)
    assert r.counts["fields_max_rel_diff"] == 0.0
    # a field off by 1e-9 relative, a spawner missing, one RPM cell off
    bad = copy.deepcopy(records)
    rid, hexes = bad[10]["crosscheck_dp8"]["gpm"][3]
    values = probes.doubles(hexes)
    values[1] *= 1 + 1e-9
    bad[10]["crosscheck_dp8"]["gpm"][3] = [rid, "".join(probes.dhex(v) for v in values)]
    del bad[20]["crosscheck_dp8"]["rpm_first"]["spawners"][0]
    k, h = bad[30]["crosscheck_dp8"]["rpm_first"]["rpm"][1]
    bad[30]["crosscheck_dp8"]["rpm_first"]["rpm"][1] = [k, probes.dhex(probes.doubles(h)[0] * 2 + 1)]
    r = rpm.check_dp8(_run([], [], mode="checkpoint", override=True, records=bad), env)
    found = sorted((e["table"], e.get("day"), e.get("worst_field") or e.get("present") or e.get("stat_name")) for e in r.examples)
    assert r.mismatches == 3, found
    assert found[0][:2] == ("DP8", records[10]["day"]) and found[0][2] == "fight_time"
    assert found[1][:2] == ("DP8", records[20]["day"]) and found[1][2] == "oracle_only"
    assert found[2][:2] == ("DP8_rpm", records[30]["day"])


def _gpm_run(env, shipped, order_lag: int):
    """Day snapshots whose CurrentGpm is the oracle's own RpmFirst chain on their state (current health full)."""
    out, rpm_ = [], sc.initial_rpm()
    for i, snap in enumerate(shipped.time_chunk_snapshots[:12]):
        s = X.Snap("TimeChunkSnapshots", i, replace(snap, time_chunk_index=i), None, [])
        rpm_ = rpm._rpm(env, rpm.day_state(env, s, i - order_lag), rpm_)
        stats = [replace(st, current_gpm=rpm_.get(st.key, 0.0)) for st in snap.stats]
        out.append(X.Snap("TimeChunkSnapshots", i, replace(snap, time_chunk_index=i, stats=stats), None, []))
    return out


def test_x3_x7_follow_rpm_first_and_catch_a_planted_cell(env, shipped):
    full = _gpm_run(env, shipped, 1)
    for check in (rpm.check_x3, rpm.check_x7):
        r = check(_run([], full), env)
        assert r.status == "pass" and r.counts["bit_equal"] == r.items == 12 * 30
    assert rpm.check_x7(_run([], full), env).counts["modifier_first_cells_off"] > 0
    st = full[5].snapshot.stats[0]
    full[5].snapshot.stats[0] = SimulationStat(st.key, st.value, st.stats_from_features_flat, st.percent_multiplier,
                                               st.total_flat_value, st.total_value, st.current_gpm * (1 + 1e-9))
    r = rpm.check_x3(_run([], full), env)
    assert r.mismatches >= 1 and r.examples[0]["time_chunk_index"] == 5
    # ModifierFirst data fails RpmFirst's X7
    r = rpm.check_x7(_run([], _gpm_run(env, shipped, 0)), env)
    assert r.status == "fail"
    assert rpm.check_x3(_run([], [], override=True), env).status == "vacuous"


def test_x6_clock_day_list_and_values(env, shipped, tmp_path):
    base = invariants.base_values(env)
    days = []
    for i in range(6):
        s = shipped.time_chunk_snapshots[0]
        stats = [replace(st, value=base.get(st.key, 0.0)) for st in s.stats]
        days.append(X.Snap("TimeChunkSnapshots", i, replace(s, time_chunk_index=i, total_playtime=float(1440 * i + 4),
                                                             stats=stats), {"exported_index": [0, 1, 2, 3, 4, 5][i]}, []))
    daily = [{"day": i, "playtime": 0.0, "total_playtime": 1440.0 * i, "clears": 0} for i in range(6)]
    r = invariants.check_x6(_run([], days, daily=daily), env, tmp_path)
    assert r.status == "pass", r.examples
    assert set(r.vacuous) == {"values_rewards", "charges", "dafc", "unlocks"}
    days[3].snapshot.stats[2] = replace(days[3].snapshot.stats[2], value=days[3].snapshot.stats[2].value + 1.0)
    days[4] = replace(days[4], snapshot=replace(days[4].snapshot, total_playtime=float(1440 * 5)))
    r = invariants.check_x6(_run([], days, daily=daily), env)
    kinds = sorted(e["invariant"] for e in r.examples)
    assert kinds == ["time_chunk", "values"], r.examples


def test_statuses_and_csv(tmp_path):
    c = X.Check("T", "t", ("a",))
    assert c.result(tmp_path).status == "vacuous"
    c.item(True, a=1)
    c.vacuous_part("p", "why")
    r = c.result(tmp_path)
    assert (r.status, r.items, r.vacuous) == ("pass", 1, {"p": "why"})
    c.item(False, a=2)
    r = c.result(tmp_path)
    assert r.status == "fail" and r.examples == [{"table": "T", "a": 2, "ok": 0}]
    assert (tmp_path / "T.csv").read_text() == "a,ok\n1,1\n2,0\n"
    assert X.rel_diff(1.0, 1.0) == 0.0 and X.rel_diff(math.nan, math.nan) == 0.0 and X.rel_diff(1.0, math.inf) == math.inf
    assert X.forecast_value(1, 100.0, 0.5, 2.0) == 300.0 and X.forecast_value(3, 4.0, 0.5, 2.0) == 4.0
